-- Online (Razorpay) payments are saved by the server for the signed-in student. They must not depend on the manual
-- "student UPI reference" switches, which only govern payments a student types in by hand.
do $$ declare f text; old text; new text; begin
  select pg_get_functiondef(p.oid) into f from pg_proc p where p.proname = 'guard_education_payment' and p.pronamespace = 'public'::regnamespace;
  old := E'IF NEW.student_id <> auth.uid() OR NEW.status <> ''Pending Verification'' OR NEW.payment_method <> ''UPI'' OR NEW.currency <> ''INR'' THEN RAISE EXCEPTION ''Students may only submit their own UPI payment for verification''; END IF;\n    IF NOT coalesce((cfg->''payment_gateways''->>''phonepe_upi_enabled'')::boolean, false) THEN RAISE EXCEPTION ''Student UPI payments are disabled''; END IF;\n    IF NOT EXISTS (SELECT 1 FROM public.system_config WHERE key = ''payment_gateways'' AND (value->''upi''->>''enabled'')::boolean AND (value->''divisions''->''education''->>''allowUpi'')::boolean) THEN RAISE EXCEPTION ''UPI gateway is not enabled''; END IF;';
  new := E'IF NEW.status <> ''Pending Verification'' OR NEW.payment_method <> ''UPI'' OR NEW.currency <> ''INR'' THEN RAISE EXCEPTION ''Students may only submit their own UPI payment for verification''; END IF;\n    IF auth.role() <> ''service_role'' THEN\n      IF NEW.student_id <> auth.uid() THEN RAISE EXCEPTION ''Students may only submit their own UPI payment for verification''; END IF;\n      IF NOT coalesce((cfg->''payment_gateways''->>''phonepe_upi_enabled'')::boolean, false) THEN RAISE EXCEPTION ''Student UPI payments are disabled''; END IF;\n      IF NOT EXISTS (SELECT 1 FROM public.system_config WHERE key = ''payment_gateways'' AND (value->''upi''->>''enabled'')::boolean AND (value->''divisions''->''education''->>''allowUpi'')::boolean) THEN RAISE EXCEPTION ''UPI gateway is not enabled''; END IF;\n    END IF;';
  if position(old in f) = 0 then raise exception 'guard text changed'; end if;
  execute replace(f, old, new);
end $$;
